/// Is this crate root nothing but its documentation and the one generated `include!`?
///
/// THE FLOOR TEST. A root that answers yes holds no program at all: its `//!` block becomes a doc
/// record and its `include!` is what the shared root already does, so the file — and with it the
/// crate's whole `src/` directory — can go. A root that answers no still holds code that is not in the
/// graph, and moving it is the LARGER migration this is not (48 crates, ~16,800 lines).
///
/// Comments count as absent because the migrated roots are mostly comment: `migrate-crate` writes a
/// header naming every file that stopped existing, and that header is a signpost to the graph rather
/// than part of the program. An INNER ATTRIBUTE does not: `#![forbid(unsafe_code)]` changes what the
/// crate accepts, so a root carrying one is not bare until it moves to the manifest's `[lints]` table.
pub fn root_is_bare(lib_src: &str) -> bool {
    let mut saw_include = false;
    for line in lib_src.lines() {
        let t = line.trim();
        if t.is_empty() || t.starts_with("//") {
            continue;
        }
        if t.starts_with("include!(concat!(env!(\"OUT_DIR\")") {
            saw_include = true;
            continue;
        }
        return false;
    }
    saw_include
}
